/// <summary>
/// Extension of InventUpd_Estimated to customize catch weight quantity behavior.
/// </summary>
[ExtensionOf(classStr(InventUpd_Estimated))]
internal final class METInventUpd_Estimated_Extension
{
}

Method.Source:
/// <summary>
/// This method Adjust the Invent quantity in purchline.
/// </summary>
/// <param name = "_movement">InventMovement instance</param>
public static void pdsCWQtyModified(InventMovement _movement)
{
    if (_movement.buffer() is PurchLine)
    {
        PurchLine _purchLine = _movement.buffer() as PurchLine;
        _purchLine.PdsCWRemainInventPhysical = 0;
    }

    next pdsCWQtyModified(_movement);
}
